const m = $input.first().json.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!m || m.type !== 'text') return [];
const contact = $input.first().json.entry?.[0]?.changes?.[0]?.value?.contacts?.[0] || {};
return [{ json: { from: m.from, text: m.text.body, name: contact.profile?.name || 'there', waId: m.id } }];

const raw = ($input.first().json.message && $input.first().json.message.content) || '';
let p;
try { p = JSON.parse(String(raw).replace(/```json|```/g,'')); } catch(e) { p = { reply: 'Thanks for messaging {{ $env.BUSINESS_NAME }}! We will reply shortly.', intent: 'other' }; }
const prev = JSON.parse(JSON.stringify($('Extract Message').first().json));
return [{ json: { ...prev, reply: p.reply, intent: p.intent } }];
